import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import './Forum.css';
import ThreadList from '../Thread/ThreadList';
import LastThreadInfo from '../Thread/LastThreadInfo';

const ForumDetail = () => {
    const { id } = useParams();
    const [forum, setForum] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        fetch(`http://localhost:8000/api/forums/${id}`) // Update this to your backend endpoint
            .then(response => response.json())
            .then(data => {
                setForum(data);
                setLoading(false);
            })
            .catch(error => {
                console.error('Error fetching forum data:', error);
                setLoading(false);
            });
    }, [id]);

    if (loading) {
        return <p>Loading...</p>;
    }

    if (!forum) {
        return <p>Forum not found</p>;
    }

    return (
        <div className="forum-detail">
            <nav className="breadcrumb">
                {forum.breadcrumb.map((crumb, index) => (
                    <span key={index}>
                        <Link to={crumb.url}>{crumb.name}</Link>
                        {index < forum.breadcrumb.length - 1 && " > "}
                    </span>
                ))}
            </nav>

            <h2>{forum.name}</h2>
            <p>{forum.description}</p>

            {forum.subForums.length > 0 && (
                <div className="subforums">
                    <h3>Subforums</h3>
                    <ul>
                        {forum.subForums.map(subForum => (
                            <li key={subForum.id} className="subforum-item">
                                <div className="subforum-info">
                                    <h4 className="subforum-title">
                                        <Link to={`/forum/${subForum.id}`}>{subForum.name}</Link>
                                    </h4>
                                    <p>{subForum.description}</p>
                                </div>
                                <LastThreadInfo lastThread={subForum.lastThread} />
                            </li>
                        ))}
                    </ul>
                </div>
            )}

            <div className="threads">
                <h3>Threads</h3>
                <ThreadList forumId={forum.id} />
            </div>
        </div>
    );
};

export default ForumDetail;
